var shader = Shader.Find("Universal Render Pipeline/Particles/Unlit");
if (shader == null) { Debug.LogError("URP Particles/Unlit shader not found!"); return; }

System.IO.Directory.CreateDirectory(Application.dataPath + "/Materials/Garden");

var waterMat = new Material(shader);
waterMat.name = "WaterParticle";
waterMat.SetColor("_BaseColor", new Color(0.2f, 0.55f, 1.0f, 0.85f));
waterMat.SetFloat("_Surface", 1f);
waterMat.SetFloat("_Blend", 0f);
waterMat.renderQueue = 3000;
AssetDatabase.CreateAsset(waterMat, "Assets/Materials/Garden/WaterParticle.mat");

var spillMat = new Material(shader);
spillMat.name = "SpillParticle";
spillMat.SetColor("_BaseColor", new Color(0.4f, 0.75f, 1.0f, 0.6f));
spillMat.SetFloat("_Surface", 1f);
spillMat.SetFloat("_Blend", 0f);
spillMat.renderQueue = 3000;
AssetDatabase.CreateAsset(spillMat, "Assets/Materials/Garden/SpillParticle.mat");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

var waterSpout = GameObject.Find("WaterSpout");
if (waterSpout != null) {
    var pr = waterSpout.GetComponent<ParticleSystemRenderer>();
    if (pr != null) { pr.sharedMaterial = waterMat; EditorUtility.SetDirty(pr); Debug.Log("WaterSpout material assigned."); }
    else Debug.LogError("No ParticleSystemRenderer on WaterSpout");
} else Debug.LogError("WaterSpout not found!");

var spillEffect = GameObject.Find("SpillEffect");
if (spillEffect != null) {
    var pr = spillEffect.GetComponent<ParticleSystemRenderer>();
    if (pr != null) { pr.sharedMaterial = spillMat; EditorUtility.SetDirty(pr); Debug.Log("SpillEffect material assigned."); }
    else Debug.LogError("No ParticleSystemRenderer on SpillEffect");
} else Debug.LogError("SpillEffect not found!");

Debug.Log("Done: water materials created and assigned.");
